    var lines = input.Split(new[] { '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries);

    var red = new List<(int x, int y)>();
    var xsSet = new SortedSet<int>();
    var ysSet = new SortedSet<int>();

    foreach (var line in lines)
    {
        var p = line.Split(',');
        int x = int.Parse(p[0]);
        int y = int.Parse(p[1]);

        red.Add((x, y));

        xsSet.Add(x - 1);
        xsSet.Add(x);
        xsSet.Add(x + 1);

        ysSet.Add(y - 1);
        ysSet.Add(y);
        ysSet.Add(y + 1);
    }

    var xs = new List<int>(xsSet);
    var ys = new List<int>(ysSet);

    int w = xs.Count;
    int h = ys.Count;

    var xIndex = new Dictionary<int, int>();
    var yIndex = new Dictionary<int, int>();

    for (int i = 0; i < w; i++)
        xIndex[xs[i]] = i;

    for (int i = 0; i < h; i++)
        yIndex[ys[i]] = i;

    int[,] grid = new int[w, h];

    foreach (var (x, y) in red)
    {
        int cx = xIndex[x];
        int cy = yIndex[y];
        grid[cx, cy] = 2;
    }

    for (int i = 0; i < red.Count; i++)
    {
        var (x1, y1) = red[i];
        var (x2, y2) = red[(i + 1) % red.Count];

        int cx1 = xIndex[x1];
        int cy1 = yIndex[y1];
        int cx2 = xIndex[x2];
        int cy2 = yIndex[y2];

        if (cx1 == cx2)
        {
            int ya = Math.Min(cy1, cy2);
            int yb = Math.Max(cy1, cy2);
            for (int y = ya; y <= yb; y++)
            {
                if (grid[cx1, y] == 0)
                    grid[cx1, y] = 1;
            }
        }
        else if (cy1 == cy2)
        {
            int xa = Math.Min(cx1, cx2);
            int xb = Math.Max(cx1, cx2);
            for (int x = xa; x <= xb; x++)
            {
                if (grid[x, cy1] == 0)
                    grid[x, cy1] = 1;
            }
        }
    }

    bool[,] visited = new bool[w, h];

    void FloodFill(int sx, int sy)
    {
        var q = new Queue<(int x, int y)>();
        q.Enqueue((sx, sy));
        visited[sx, sy] = true;

        int[] dx = { 1, -1, 0, 0 };
        int[] dy = { 0, 0, 1, -1 };

        while (q.Count > 0)
        {
            var (x, y) = q.Dequeue();

            for (int d = 0; d < 4; d++)
            {
                int nx = x + dx[d];
                int ny = y + dy[d];

                if (nx < 0 || ny < 0 || nx >= w || ny >= h)
                    continue;

                if (!visited[nx, ny] && grid[nx, ny] == 0)
                {
                    visited[nx, ny] = true;
                    q.Enqueue((nx, ny));
                }
            }
        }
    }

    FloodFill(0, 0);

    for (int x = 0; x < w; x++)
    {
        for (int y = 0; y < h; y++)
        {
            if (!visited[x, y] && grid[x, y] == 0)
                grid[x, y] = 1;
        }
    }

    long best = 0;

    for (int i = 0; i < red.Count; i++)
    {
        for (int j = i + 1; j < red.Count; j++)
        {
            int x1 = red[i].x;
            int y1 = red[i].y;
            int x2 = red[j].x;
            int y2 = red[j].y;

            int cx1 = xIndex[x1];
            int cy1 = yIndex[y1];
            int cx2 = xIndex[x2];
            int cy2 = yIndex[y2];

            int left = Math.Min(cx1, cx2);
            int right = Math.Max(cx1, cx2);
            int bottom = Math.Min(cy1, cy2);
            int top = Math.Max(cy1, cy2);

            bool valid = true;

            for (int x = left; x <= right && valid; x++)
            {
                for (int y = bottom; y <= top; y++)
                {
                    if (grid[x, y] == 0)
                    {
                        valid = false;
                        break;
                    }
                }
            }

            if (!valid) continue;

            long origLeft = Math.Min(x1, x2);
            long origRight = Math.Max(x1, x2);
            long origBottom = Math.Min(y1, y2);
            long origTop = Math.Max(y1, y2);

            long widthTiles = origRight - origLeft + 1;
            long heightTiles = origTop - origBottom + 1;
            long area = widthTiles * heightTiles;

            if (area > best)
                best = area;
        }
    }

    Console.WriteLine(best);
